namespace Members\Service;

use Krystal\Date\TimeHelper;
use Krystal\Stdlib\VirtualEntity;

/**
 * Domain entity for an event.
 *
 * Encapsulates business rules (isPast, isOfficial, hasLink) and
 * UI helpers (status badge class, formatted dates) so templates
 * stay declarative and free of date-parsing logic.
 */
final class EventEntity extends VirtualEntity
{
    /**
     * Cover image sizes generated by the image manager
     *
     * @const string
     */
    const COVER_THUMB = '400x225';
    const COVER_CARD = '800x450';
    const COVER_FULL = '1600x900';

    /**
     * Event status constants
     *
     * @const string
     */
    const STATUS_PENDING = 'pending';
    const STATUS_APPROVED = 'approved';
    const STATUS_REJECTED = 'rejected';

    /**
     * Location source constants
     *
     * @const string
     */
    const LOCATION_SOURCE_MANUAL = 'manual';
    const LOCATION_SOURCE_URL = 'url';
    const LOCATION_SOURCE_NONE = 'none';

    /**
     * A time of 00:00 means "no specific time was set" — the event
     * is date-only. Rendering "00:00" is noise, so every display
     * helper treats it as absent.
     *
     * @const string
     */
    const MIDNIGHT = '00:00';

    /**
     * Tells whether the event is official (created by admin on behalf of the association)
     *
     * @return bool
     */
    public function isOfficial()
    {
        return $this->getCreatorId() === null;
    }

    /**
     * Tells whether the event has already ended
     *
     * Uses ends_at when present, otherwise falls back to starts_at.
     * Returns false when no reference time is set, so a malformed
     * event never renders as "past".
     *
     * @return bool
     */
    public function isPast()
    {
        $referenceTime = $this->getEndsAt();

        if (empty($referenceTime)) {
            $referenceTime = $this->getStartsAt();
        }

        if (empty($referenceTime)) {
            return false;
        }

        $timestamp = strtotime($referenceTime);

        if ($timestamp === false) {
            return false;
        }

        return $timestamp < time();
    }

    /**
     * Tells whether the event has a registration link
     *
     * @return bool
     */
    public function hasLink()
    {
        $link = $this->getLink();

        return $link !== null && $link !== '';
    }

    /**
     * Tells whether the event has a location name
     *
     * @return bool
     */
    public function hasLocation()
    {
        $location = $this->getLocationName();

        return $location !== null && $location !== '';
    }

    /**
     * Tells whether the event has valid coordinates
     *
     * @return bool
     */
    public function hasCoordinates()
    {
        return $this->getLatitude() !== null && $this->getLongitude() !== null;
    }

    /**
     * Tells whether the event has a description
     *
     * @return bool
     */
    public function hasDescription()
    {
        $description = $this->getDescription();

        return $description !== null && $description !== '';
    }

    /**
     * Tells whether an explicit organizer name is set
     *
     * @return bool
     */
    public function hasOrganizer()
    {
        $organizer = $this->getOrganizer();

        return $organizer !== null && $organizer !== '';
    }

    /**
     * Tells whether the event has a creator (user or admin)
     *
     * @return bool
     */
    public function hasCreator()
    {
        return $this->getCreatorName() !== null;
    }

    /**
     * Tells whether the event has a meaningful start time
     *
     * @return bool
     */
    public function hasStartTime()
    {
        return $this->hasMeaningfulTime($this->getStartsAt());
    }

    /**
     * Tells whether the event has a meaningful end time
     *
     * @return bool
     */
    public function hasEndTime()
    {
        return $this->hasMeaningfulTime($this->getEndsAt());
    }

    /**
     * Determines whether a datetime carries a time other than midnight
     *
     * @param string|null $value
     * @return bool
     */
    private function hasMeaningfulTime($value)
    {
        if (empty($value)) {
            return false;
        }

        $timestamp = strtotime($value);

        if ($timestamp === false) {
            return false;
        }

        return date('H:i', $timestamp) !== self::MIDNIGHT;
    }

    /**
     * Returns the cover URL for a given size, or null when there is none
     *
     * @param string $size One of the COVER_* constants
     * @return string|null
     */
    public function getCoverUrl($size = self::COVER_CARD)
    {
        if (!$this->hasCover()) {
            return null;
        }

        $bag = $this->getCoverBag();

        if (!$bag) {
            return null;
        }

        return $bag->getUrl($size);
    }

    /**
     * Checks whether event has attached cover file
     *
     * @return boolean
     */
    public function hasCover()
    {
        return !empty($this->getCover());
    }

    /**
     * Returns the organizer label to display
     *
     * @return string
     */
    public function getOrganizerName()
    {
        if ($this->hasOrganizer()) {
            return (string) $this->getOrganizer();
        }

        if ($this->hasCreator()) {
            return (string) $this->getCreatorName();
        }

        return '';
    }

    /**
     * Returns a title that is never blank
     *
     * @return string
     */
    public function getDisplayTitle()
    {
        $title = $this->getTitle();

        if ($title !== null && $title !== '') {
            return (string) $title;
        }

        return '#' . (int) $this->getId();
    }

    /**
     * Returns a trimmed plain-text summary of the event description
     *
     * @param int $length
     * @return string
     */
    public function getShortDescription($length = 150)
    {
        if (!$this->hasDescription()) {
            return '';
        }

        $plainText = trim(strip_tags((string) $this->getDescription()));

        if ($plainText === '') {
            return '';
        }

        if (function_exists('mb_substr')) {
            return mb_substr($plainText, 0, $length, 'UTF-8');
        }

        return substr($plainText, 0, $length);
    }

    /**
     * Returns the Google Maps directions URL for the event coordinates
     *
     * @return string
     */
    public function getDirectionsUrl()
    {
        if (!$this->hasCoordinates()) {
            return '';
        }

        $destination = urlencode((string) $this->getLatitude() . ',' . (string) $this->getLongitude());

        return 'https://www.google.com/maps/dir/?api=1&destination=' . $destination;
    }

    /**
     * Returns the Bootstrap badge class for the current status
     *
     * @return string
     */
    public function getStatusBadgeClass()
    {
        $map = [
            self::STATUS_PENDING => 'warning',
            self::STATUS_APPROVED => 'success',
            self::STATUS_REJECTED => 'danger',
        ];

        $status = $this->getStatus();

        return isset($map[$status]) ? $map[$status] : 'secondary';
    }

    /**
     * Returns the translation key for the current status
     *
     * @return string
     */
    public function getStatusTranslationKey()
    {
        $map = [
            self::STATUS_PENDING => 'Pending approval',
            self::STATUS_APPROVED => 'Approved',
            self::STATUS_REJECTED => 'Rejected',
        ];

        $status = $this->getStatus();

        return isset($map[$status]) ? $map[$status] : (string) $status;
    }

    /**
     * Returns the formatted start date (e.g. "Nov 22, 2026")
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getFormattedDate($locale)
    {
        $startsAt = $this->getStartsAt();

        if (empty($startsAt)) {
            return '';
        }

        return TimeHelper::formatLocalized($startsAt, $locale, 'MMM d, y');
    }

    /**
     * Returns the formatted start time (e.g. "18:55")
     *
     * Returns empty string when the time is midnight (00:00),
     * because midnight means "no specific time was set".
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getFormattedTime($locale)
    {
        if (!$this->hasStartTime()) {
            return '';
        }

        return TimeHelper::formatLocalized($this->getStartsAt(), $locale, 'HH:mm');
    }

    /**
     * Returns the full formatted start date and time (e.g. "Saturday, November 22, 2026")
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getFormattedStartDateTime($locale)
    {
        $startsAt = $this->getStartsAt();

        if (empty($startsAt)) {
            return '';
        }

        return TimeHelper::formatLocalized($startsAt, $locale, 'EEEE, MMMM d, y');
    }

    /**
     * Returns the month abbreviation for the start date (e.g. "NOV")
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getStartMonth($locale)
    {
        $startsAt = $this->getStartsAt();

        if (empty($startsAt)) {
            return '';
        }

        $month = TimeHelper::formatLocalized($startsAt, $locale, 'MMM');

        return mb_strtoupper($month, 'UTF-8');
    }

    /**
     * Returns the day number for the start date (e.g. "22")
     *
     * @return int
     */
    public function getStartDay()
    {
        $startsAt = $this->getStartsAt();

        if (empty($startsAt)) {
            return 0;
        }

        $timestamp = strtotime($startsAt);

        if ($timestamp === false) {
            return 0;
        }

        return (int) date('d', $timestamp);
    }

    /**
     * Returns the formatted end time (e.g. "22:57")
     *
     * Returns empty string when the time is midnight (00:00),
     * because midnight means "no specific time was set".
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getFormattedEndTime($locale)
    {
        if (!$this->hasEndTime()) {
            return '';
        }

        return TimeHelper::formatLocalized($this->getEndsAt(), $locale, 'HH:mm');
    }

    /**
     * Returns the "HH:MM — HH:MM" / "HH:MM" label, or '' for date-only events
     *
     * @param string $locale Locale code
     * @return string
     */
    public function getTimeRange($locale)
    {
        $start = $this->getFormattedTime($locale);

        if ($start === '') {
            return '';
        }

        $end = $this->getFormattedEndTime($locale);

        return $end === '' ? $start : $start . ' — ' . $end;
    }

    /**
     * Returns the conversion rate (clicks / views * 100)
     *
     * @return float
     */
    public function getConversionRate()
    {
        $views = $this->getViewsCount();

        if ($views <= 0) {
            return 0.0;
        }

        return round(($this->getClicksCount() / $views) * 100, 2);
    }
}